-- LabForge initial schema (Milestone 1).
--
-- Content (challenges, steps, hints, choices, evidence) is kept strictly apart from
-- user progress (attempts, attempt_steps, notes). Progress rows point at the exact
-- challenge version they were started against; versions are never edited in place
-- once attempted (enforced in the service layer, backed by ON DELETE RESTRICT here).
--
-- Timestamps are RFC 3339 UTC text with millisecond precision, generated by SQLite.
-- Internal integer keys are fine: this is a single-user local database and no id is
-- exposed to a network. Stable, human-meaningful identity lives in `slug` / `step_key`.

------------------------------------------------------------------------------
-- Content
------------------------------------------------------------------------------

CREATE TABLE challenges (
    id            INTEGER PRIMARY KEY,
    slug          TEXT    NOT NULL
                  CHECK (length(slug) BETWEEN 1 AND 64 AND slug NOT GLOB '*[^a-z0-9-]*'),
    version       INTEGER NOT NULL CHECK (version >= 1),
    source        TEXT    NOT NULL CHECK (source IN ('bundled', 'custom')),
    title         TEXT    NOT NULL CHECK (length(title) BETWEEN 1 AND 120),
    summary       TEXT    NOT NULL CHECK (length(summary) BETWEEN 1 AND 500),
    difficulty    TEXT    NOT NULL CHECK (difficulty IN ('beginner', 'intermediate', 'advanced')),
    objectives_md TEXT    NOT NULL CHECK (length(objectives_md) <= 5000),
    created_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    UNIQUE (slug, version)
);

CREATE TABLE challenge_steps (
    id                  INTEGER PRIMARY KEY,
    challenge_id        INTEGER NOT NULL REFERENCES challenges (id) ON DELETE CASCADE,
    step_key            TEXT    NOT NULL
                        CHECK (length(step_key) BETWEEN 1 AND 64 AND step_key NOT GLOB '*[^a-z0-9-]*'),
    position            INTEGER NOT NULL CHECK (position >= 1),
    -- task:  learner confirms they did it
    -- check: knowledge check, answered through step_choices
    -- note:  complete only once the attempt's note has content
    kind                TEXT    NOT NULL CHECK (kind IN ('task', 'check', 'note')),
    title               TEXT    NOT NULL CHECK (length(title) BETWEEN 1 AND 120),
    instructions_md     TEXT    NOT NULL CHECK (length(instructions_md) BETWEEN 1 AND 10000),
    completion_criteria TEXT    NOT NULL CHECK (length(completion_criteria) BETWEEN 1 AND 500),
    UNIQUE (challenge_id, step_key),
    UNIQUE (challenge_id, position)
);

CREATE TABLE step_hints (
    id      INTEGER PRIMARY KEY,
    step_id INTEGER NOT NULL REFERENCES challenge_steps (id) ON DELETE CASCADE,
    position INTEGER NOT NULL CHECK (position >= 1),
    body_md TEXT    NOT NULL CHECK (length(body_md) BETWEEN 1 AND 2000),
    UNIQUE (step_id, position)
);

CREATE TABLE step_choices (
    id          INTEGER PRIMARY KEY,
    step_id     INTEGER NOT NULL REFERENCES challenge_steps (id) ON DELETE CASCADE,
    position    INTEGER NOT NULL CHECK (position >= 1),
    label       TEXT    NOT NULL CHECK (length(label) BETWEEN 1 AND 300),
    is_correct  INTEGER NOT NULL CHECK (is_correct IN (0, 1)),
    explanation TEXT    NOT NULL CHECK (length(explanation) BETWEEN 1 AND 1000),
    UNIQUE (step_id, position)
);
-- A knowledge check has exactly one correct answer.
CREATE UNIQUE INDEX uq_step_choices_one_correct ON step_choices (step_id) WHERE is_correct = 1;

CREATE TABLE challenge_evidence (
    id           INTEGER PRIMARY KEY,
    challenge_id INTEGER NOT NULL REFERENCES challenges (id) ON DELETE CASCADE,
    evidence_key TEXT    NOT NULL
                 CHECK (length(evidence_key) BETWEEN 1 AND 64 AND evidence_key NOT GLOB '*[^a-z0-9-]*'),
    position     INTEGER NOT NULL CHECK (position >= 1),
    kind         TEXT    NOT NULL CHECK (kind IN ('packet_summary')),
    title        TEXT    NOT NULL CHECK (length(title) BETWEEN 1 AND 120),
    -- Free-form payload whose shape depends on `kind`; the Rust layer validates it.
    content      TEXT    NOT NULL CHECK (json_valid(content)),
    UNIQUE (challenge_id, evidence_key),
    UNIQUE (challenge_id, position)
);

------------------------------------------------------------------------------
-- User progress
------------------------------------------------------------------------------

CREATE TABLE attempts (
    id           INTEGER PRIMARY KEY,
    challenge_id INTEGER NOT NULL REFERENCES challenges (id) ON DELETE RESTRICT,
    status       TEXT    NOT NULL CHECK (status IN ('in_progress', 'completed')),
    started_at   TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    completed_at TEXT,
    CHECK ((status = 'completed') = (completed_at IS NOT NULL))
);
CREATE INDEX idx_attempts_challenge ON attempts (challenge_id, started_at);
-- Retries are new attempts, but only one may be open per challenge at a time.
CREATE UNIQUE INDEX uq_attempts_one_open ON attempts (challenge_id) WHERE status = 'in_progress';

CREATE TABLE attempt_steps (
    attempt_id         INTEGER NOT NULL REFERENCES attempts (id) ON DELETE CASCADE,
    step_id            INTEGER NOT NULL REFERENCES challenge_steps (id) ON DELETE RESTRICT,
    status             TEXT    NOT NULL CHECK (status IN ('not_started', 'completed')),
    completed_at       TEXT,
    selected_choice_id INTEGER REFERENCES step_choices (id) ON DELETE RESTRICT,
    PRIMARY KEY (attempt_id, step_id),
    CHECK ((status = 'completed') = (completed_at IS NOT NULL))
) WITHOUT ROWID;
CREATE INDEX idx_attempt_steps_step ON attempt_steps (step_id);

CREATE TABLE notes (
    id         INTEGER PRIMARY KEY,
    -- One Markdown notebook per attempt; a retry starts with a fresh one.
    attempt_id INTEGER NOT NULL UNIQUE REFERENCES attempts (id) ON DELETE CASCADE,
    body_md    TEXT    NOT NULL CHECK (length(body_md) <= 100000),
    created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
